def obtain_github_token():
    """
    Create a new GitHub OAuth token after confirming user credentials.
    """
    hdrs = {"User-Agent": "edx-release"}
    payload = {"note": "edx-release", "scopes": ["repo"]}
    user = raw_input("GitHub username: ")
    pwd = getpass.getpass("GitHub password: ")
    resp = requests.post(
        "https://api.github.com/authorizations",
        auth=(user, pwd),
        headers=hdrs,
        data=json.dumps(payload),
    )
    otp = resp.headers.get("X-GitHub-OTP")
    if (not resp.ok) and otp and otp.startswith("required;"):
        hdrs["X-GitHub-OTP"] = raw_input("Two‑factor authentication code: ")
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=hdrs,
            data=json.dumps(payload),
        )
    if not resp.ok:
        msg = resp.json()["message"]
        if msg != "Validation Failed":
            return True
        token_id = get_github_auth_id(user, pwd, "edx-release")
        if token_id:
            delete_github_auth_token(user, pwd, token_id)
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=hdrs,
            data=json.dumps(payload),
        )
    if not resp.ok:
        return True
    return (user, resp.json()["token"])

