class ApiHttpBasicAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        auth_header = request.META.get('HTTP_AUTHORIZATION')
        if not auth_header:
            return

        try:
            auth_type, data = auth_header.split()
            if auth_type != 'Basic':
                return JSONResponseUnauthorized(request, 'Error with HTTP Basic Auth')
            user_pass = base64.b64decode(data)
        except Exception:
            return JSONResponseUnauthorized(request, 'Error with HTTP Basic Auth')

        parts = user_pass.split(':', 1)
        if len(parts) != 2:
            return JSONResponseUnauthorized(
                request,
                'Invalid Authorization header. Value should be "Basic <base64(username:password)>".'
            )

        username, password = parts
        user = _get_user(username)
        if user is None or not user.check_password(password):
            return JSONResponseUnauthorized(request, 'Username and password don\'t match')

        request.user = user
        return


