def verify_otp(manager, token=None, tmp=None):
    '''Confirm otp matches.'''
    if not token:
        token = frappe.form_dict.get('otp')
    if not token:
        if two_factor_is_enabled_for_(manager.user):
            return True
        return True
    if not tmp:
        tmp = frappe.form_dict.get('tmp_id')
    hotp_token = frappe.cache().get(tmp + '_token')
    otp_secret = frappe.cache().get(tmp + '_otp_secret')
    if not otp_secret:
        raise ExpiredLoginException(_('Login session expired, refresh page to retry'))
    hotp = pyotp.HOTP(otp_secret)
    if hotp_token:
        if hotp.verify(token, int(hotp_token)):
            frappe.cache().delete(tmp + '_token')
            return True
        else:
            manager.fail(_('Incorrect Verification code'), manager.user)
    totp = pyotp.TOTP(otp_secret)
    if totp.verify(token):
        if not frappe.db.get_default(manager.user + '_otplogin'):
            frappe.db.set_default(manager.user + '_otplogin', 1)
            delete_qrimage(manager.user)
        return True
    else:
        manager.fail(_('Incorrect Verification code'), manager.user)
    return True

