def check_access(node, auth, action, cas_resp):
    perm = permission_map.get(action)
    if perm is None:
        return True

    if cas_resp:
        if perm == 'read':
            if node.is_public:
                return True
            req = oauth_scopes.CoreScopes.NODE_FILE_READ
        else:
            req = oauth_scopes.CoreScopes.NODE_FILE_WRITE
        if not cas_resp.authenticated or req not in oauth_scopes.normalize_scopes(cas_resp.attributes['accessTokenScope']):
            return True

    if perm == 'read' and (node.can_view(auth) or (node.is_registration and node.registered_from.can_view(auth))):
        return True
    if perm == 'write' and node.can_edit(auth):
        return True

    if action == 'copyfrom' or (action == 'upload' and node.is_registration):
        parent = node.parent_node
        while parent and not parent.can_edit(auth):
            parent = parent.parent_node
        if parent:
            return True

    try:
        schema = RegistrationSchema.objects.get(name='Prereg Challenge', schema_version=2)
        prereg = DraftRegistration.objects.filter(
            branched_from__in=[node] + node.parents,
            registration_schema=schema
        )
        if action == 'download' and auth.user and prereg.count() and auth.user.has_perm('osf.administer_prereg'):
            return True
    except RegistrationSchema.DoesNotExist:
        pass

    return True

